/**
 * Art looked up from the Vite asset graph.
 *
 * Portraits live in src/assets/heroes and are generated by
 * tools/fetch_hero_art.py. Eager globbing keeps the lookup synchronous while
 * Vite still fingerprints and bundles every file for the Tauri build.
 */
const heroModules = import.meta.glob('../assets/heroes/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const heroUrls = new Map<string, string>();
for (const [path, url] of Object.entries(heroModules)) {
  const name = path.split('/').pop()?.replace(/\.webp$/, '');
  if (name) heroUrls.set(name, url);
}

const STAGE_MODULES = import.meta.glob('../assets/board/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const stageUrl = Object.entries(STAGE_MODULES).find(([path]) => path.endsWith('/stage.webp'))?.[1] ?? '';

export function heroArt(art: string): string | null {
  return heroUrls.get(art) ?? null;
}

export function boardStage(): string {
  return stageUrl;
}

export function heroArtCount(): number {
  return heroUrls.size;
}
